// Kitchen Quest local stack (EXAMPLE DATA): one origin that behaves like a Supabase project + Cloudflare Pages.
//   /                       -> the PWA in public/ (Cloudflare Pages in production)
//   /config.js              -> Supabase URL + anon key for the app (generated by scripts/write-config.mjs in production)
//   /rest/v1/*              -> real PostgREST (all app data: SQL RPC functions under RLS)
//   /auth/v1/*              -> real Supabase Auth (GoTrue): manager/owner email + password, sessions, refresh
//   /functions/v1/pin-login -> the real pin-login Edge Function, run by Deno
// There is no app logic here any more: it all lives in supabase/migrations (SQL) and supabase/functions.
import express from 'express';
import { join } from 'node:path';
import { startDatabase } from './lib/db.mjs';
import { startServices, ensureExampleLogins, PORTS, ANON_KEY, SERVICE_KEY, PUBLISHABLE_KEY, SECRET_KEY } from './lib/stack.mjs';

const ROOT = new URL('.', import.meta.url).pathname;
const PORT = Number(process.env.PORT || 8787);
const SITE = process.env.KQ_SITE_URL || `http://localhost:${PORT}`;
const args = new Set(process.argv.slice(2));

const { ep, pool } = await startDatabase({ reset: args.has('--reset') || args.has('--reset-only') });
if (args.has('--reset-only')) { await pool.end(); await ep.stop(); console.log('Database reset.'); process.exit(0); }
const services = await startServices({ db: 'kitchen_quest', siteUrl: SITE, publicUrl: `http://127.0.0.1:${PORT}` });
const made = await ensureExampleLogins(pool); if (made) console.log(`created ${made} example manager/owner logins in Supabase Auth`);

const app = express();
app.disable('x-powered-by');

// Supabase-style gateway: strip the /rest/v1, /auth/v1, /functions/v1 prefixes and forward.
const UPSTREAM = { rest: `http://127.0.0.1:${PORTS.rest}`, auth: `http://127.0.0.1:${PORTS.auth}`, fn: `http://127.0.0.1:${PORTS.fn}` };
const proxy = (target) => [express.raw({ type: () => true, limit: '2mb' }), async (req, res) => {
  const headers = {};
  for (const h of ['authorization', 'apikey', 'content-type', 'prefer', 'accept', 'range', 'x-client-info']) if (req.headers[h]) headers[h] = req.headers[h];
  // Like Supabase's gateway: the apikey decides the role unless a user's JWT is sent. New-style keys (sb_publishable_/sb_secret_)
  // are swapped for the anon/service_role JWT; a legacy JWT apikey is used as-is. Unknown keys are refused.
  const key = String(headers.apikey || ''), keyJwt = key === PUBLISHABLE_KEY ? ANON_KEY : key === SECRET_KEY ? SERVICE_KEY : key.startsWith('eyJ') ? key : null;
  if (!keyJwt && req.method !== 'OPTIONS') return res.status(401).json({ message: 'Invalid API key' });   // CORS preflights carry no key
  const bearer = String(headers.authorization || '').replace(/^Bearer\s+/i, '');
  if (keyJwt && (!bearer || bearer === key)) headers.authorization = `Bearer ${keyJwt}`;
  delete headers.apikey;
  try {
    const r = await fetch(target + req.url, { method: req.method, headers,
      body: ['GET', 'HEAD'].includes(req.method) || !req.body?.length ? undefined : req.body });
    res.status(r.status);
    for (const [k, v] of r.headers) if (!['content-encoding', 'content-length', 'transfer-encoding', 'connection'].includes(k)) res.setHeader(k, v);
    res.send(Buffer.from(await r.arrayBuffer()));
  } catch (e) { res.status(502).json({ message: 'Local service unavailable: ' + e.message }); }
}];
app.use('/rest/v1', ...proxy(UPSTREAM.rest));
app.use('/auth/v1', ...proxy(UPSTREAM.auth));
app.use('/functions/v1/pin-login', ...proxy(UPSTREAM.fn));

app.get('/config.js', (_req, res) => res.type('application/javascript').set('Cache-Control', 'no-cache')
  .send(`window.KQ_CONFIG = ${JSON.stringify({ supabaseUrl: '', anonKey: PUBLISHABLE_KEY, exampleData: true })};\n`));
app.use(express.static(join(ROOT, 'public'), { setHeaders: (res, p) => { if (/sw\.js$|config\.js$/.test(p)) res.setHeader('Cache-Control', 'no-cache'); } }));
app.get(/^\/(?!rest\/|auth\/|functions\/).*/, (_req, res) => res.sendFile(join(ROOT, 'public/index.html')));

// pg_cron stand-in: runs the jobs from cron.job (same table/schedules the migration registers) on their UTC schedule.
const field = (spec, v) => spec === '*' || spec.split(',').some(x => Number(x) === v);
const due = (sched, d) => { const [mi, h, dom, mon, dow] = sched.trim().split(/\s+/);
  return field(mi, d.getUTCMinutes()) && field(h, d.getUTCHours()) && field(dom, d.getUTCDate()) && field(mon, d.getUTCMonth() + 1) && field(dow, d.getUTCDay()); };
async function cronTick(now = new Date()) {
  try { const { rows } = await pool.query('select jobname, schedule, command from cron.job where active');
    for (const j of rows) if (due(j.schedule, now)) { await pool.query(j.command); console.log(`[cron] ${j.jobname} ran at ${now.toISOString()}`); } }
  catch (e) { console.error('[cron]', e.message); }
}
await pool.query('select public.crown_weekly_winners()');   // catch up after downtime (idempotent)
setTimeout(() => { cronTick(); setInterval(cronTick, 60_000); }, 60_000 - (Date.now() % 60_000) + 500);

app.listen(PORT, '0.0.0.0', () => console.log(`Kitchen Quest (EXAMPLE DATA) on ${SITE}  [local Supabase: PostgREST + Auth + Edge Function]`));
const stop = async () => { services.stop(); await pool.end().catch(() => {}); await ep.stop().catch(() => {}); process.exit(0); };
process.on('SIGINT', stop); process.on('SIGTERM', stop);
